import{_ as e,W as a,X as d,a2 as n}from"./framework-6a3aa88c.js";const s={},i=n(`<h1 id="第二课-亲手在-kubernetes-中运行第一个应用" tabindex="-1"><a class="header-anchor" href="#第二课-亲手在-kubernetes-中运行第一个应用" aria-hidden="true">#</a> 第二课：亲手在 Kubernetes 中运行第一个应用</h1><h2 id="这节课只做一件事" tabindex="-1"><a class="header-anchor" href="#这节课只做一件事" aria-hidden="true">#</a> 这节课只做一件事</h2><p>把 Nginx 放进 Kubernetes，亲眼看到它运行、访问它、查看日志，然后删除它。</p><p>这一课不展开集群架构，也不讲 API 分组。先获得完整操作体验，后面再解释每一步为什么有效。</p><h2 id="一、今天只认识三个新词" tabindex="-1"><a class="header-anchor" href="#一、今天只认识三个新词" aria-hidden="true">#</a> 一、今天只认识三个新词</h2><h3 id="集群-cluster" tabindex="-1"><a class="header-anchor" href="#集群-cluster" aria-hidden="true">#</a> 集群（Cluster）</h3><p>运行 Kubernetes 的整个环境叫集群。你的实验集群由 Docker Desktop 提供，目前只有一台可用机器，足够完成入门实验。</p><h3 id="pod" tabindex="-1"><a class="header-anchor" href="#pod" aria-hidden="true">#</a> Pod</h3><p>Pod 是 Kubernetes 中运行应用的最小单位。现在先把它理解成“装着容器的运行小盒子”：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Pod
└── Nginx 容器
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Pod 和容器并不完全相同，具体区别以后单独讲。</p><h3 id="kubectl" tabindex="-1"><a class="header-anchor" href="#kubectl" aria-hidden="true">#</a> kubectl</h3><p><code>kubectl</code> 是操作 Kubernetes 的命令行工具。现在只需要这样理解：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>你输入命令 → kubectl 把要求交给 Kubernetes
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="二、确认实验环境" tabindex="-1"><a class="header-anchor" href="#二、确认实验环境" aria-hidden="true">#</a> 二、确认实验环境</h2><p>打开终端并进入课程目录：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> /Users/qintianpeng/2026/code/k8s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>运行只读预检：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">bash</span> labs/00-环境预检.sh
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>最后看到下面这行即可继续：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>PASS：Kubernetes 基础实验环境可用。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="三、读懂今天要运行的文件" tabindex="-1"><a class="header-anchor" href="#三、读懂今天要运行的文件" aria-hidden="true">#</a> 三、读懂今天要运行的文件</h2><p>实验文件：<code>labs/02-第一个应用/01-nginx-pod.yaml</code></p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> v1
<span class="token key atrule">kind</span><span class="token punctuation">:</span> Pod
<span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web<span class="token punctuation">-</span>preview
<span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">containers</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> nginx
      <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span><span class="token number">1.27</span>
      <span class="token key atrule">ports</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> <span class="token key atrule">containerPort</span><span class="token punctuation">:</span> <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>现在不背字段，只把它读成一句话：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>请创建一个名为 qingyun-mall-web-preview 的 Pod，
里面运行一个 nginx:1.27 容器，
Nginx 使用 80 端口。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>YAML</th><th>白话意思</th></tr></thead><tbody><tr><td><code>kind: Pod</code></td><td>我要创建一个 Pod</td></tr><tr><td><code>name: qingyun-mall-web-preview</code></td><td>Pod 的名字</td></tr><tr><td><code>image: nginx:1.27</code></td><td>使用 Nginx 1.27 镜像</td></tr><tr><td><code>containerPort: 80</code></td><td>Nginx 在容器中使用 80 端口</td></tr></tbody></table><p>其余字段下一课再拆解。</p><h2 id="四、创建-pod" tabindex="-1"><a class="header-anchor" href="#四、创建-pod" aria-hidden="true">#</a> 四、创建 Pod</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/02-第一个应用/01-nginx-pod.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>可能看到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>pod/qingyun-mall-web-preview created
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li><code>pod/qingyun-mall-web-preview</code> 是刚创建的对象；</li><li><code>created</code> 表示 Kubernetes 接受了创建请求。</li></ul><p><code>created</code> 不等于 Nginx 已经可以访问。接下来要检查它是否真正运行。</p><h2 id="五、观察-pod-启动" tabindex="-1"><a class="header-anchor" href="#五、观察-pod-启动" aria-hidden="true">#</a> 五、观察 Pod 启动</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview <span class="token parameter variable">-w</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>get pod</code> 是查看 Pod，<code>-w</code> 是持续观察变化。可能依次看到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>NAME              READY   STATUS              RESTARTS   AGE
qingyun-mall-web-preview   0/1     ContainerCreating   0          1s
qingyun-mall-web-preview   1/1     Running             0          4s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看到 <code>Running</code> 后按 <code>Control + C</code> 退出观察。</p><table><thead><tr><th>列</th><th>当前阶段的理解</th></tr></thead><tbody><tr><td><code>READY 1/1</code></td><td>1 个容器需要就绪，目前 1 个已就绪</td></tr><tr><td><code>STATUS Running</code></td><td>Pod 已运行起来</td></tr><tr><td><code>RESTARTS 0</code></td><td>容器没有被重启</td></tr><tr><td><code>AGE</code></td><td>Pod 创建了多久</td></tr></tbody></table><p><code>Running</code> 仍不能单独证明网页正确，所以还要真正访问它。</p><h2 id="六、在浏览器中访问-nginx" tabindex="-1"><a class="header-anchor" href="#六、在浏览器中访问-nginx" aria-hidden="true">#</a> 六、在浏览器中访问 Nginx</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl port-forward pod/qingyun-mall-web-preview <span class="token number">18080</span>:80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Forwarding from 127.0.0.1:18080 -&gt; 80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>等待这行出现后再打开浏览器；端口转发刚启动的瞬间，连接可能尚未准备好。</p><p>这表示建立了一条临时通道：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>你的 Mac 端口 18080 → Pod 中 Nginx 的 80 端口
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>保持终端不要关闭，浏览器访问：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>http://127.0.0.1:18080
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到 <code>Welcome to nginx!</code>，才证明请求确实到达了 Nginx。访问完成后回到终端，按 <code>Control + C</code> 停止转发。</p><p><code>port-forward</code> 只是临时调试通道，不是正式发布方式。后面会用 Service 解决稳定访问问题。</p><h2 id="七、查看应用日志" tabindex="-1"><a class="header-anchor" href="#七、查看应用日志" aria-hidden="true">#</a> 七、查看应用日志</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl logs qingyun-mall-web-preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>刚才访问过网页后，日志中通常能看到类似记录：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>&quot;GET / HTTP/1.1&quot; 200
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>200</code> 表示这次 HTTP 请求成功。现在你完成了一个最小验证闭环：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>看运行状态 → 实际访问网页 → 从日志确认收到请求
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="八、查看启动过程" tabindex="-1"><a class="header-anchor" href="#八、查看启动过程" aria-hidden="true">#</a> 八、查看启动过程</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl describe pod qingyun-mall-web-preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>输出很多，现在不要从头背。只滚到最下面的 <code>Events</code>，它表示这个 Pod 的近期事件。通常能看到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Scheduled → Pulling → Pulled → Created → Started
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>白话意思是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>选择机器 → 拉取镜像 → 创建容器 → 启动容器
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>以后 Pod 起不来，Events 是最先查看的位置之一。</p><h2 id="九、清理实验" tabindex="-1"><a class="header-anchor" href="#九、清理实验" aria-hidden="true">#</a> 九、清理实验</h2><p>先确认目标：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后删除：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete <span class="token parameter variable">-f</span> labs/02-第一个应用/01-nginx-pod.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>最后回读：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod qingyun-mall-web-preview
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到 <code>NotFound</code>，表示清理完成。</p><h2 id="十、完整过程" tabindex="-1"><a class="header-anchor" href="#十、完整过程" aria-hidden="true">#</a> 十、完整过程</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>读取 YAML
   ↓
kubectl apply 创建 Pod
   ↓
Pod 中启动 Nginx
   ↓
port-forward 建立临时通道
   ↓
浏览器访问成功
   ↓
logs 确认请求
   ↓
delete 清理 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="十一、问题与直接回答" tabindex="-1"><a class="header-anchor" href="#十一、问题与直接回答" aria-hidden="true">#</a> 十一、问题与直接回答</h2><h3 id="为什么创建后还要执行-kubectl-get-pod" tabindex="-1"><a class="header-anchor" href="#为什么创建后还要执行-kubectl-get-pod" aria-hidden="true">#</a> 为什么创建后还要执行 <code>kubectl get pod</code>？</h3><p>因为 <code>created</code> 只说明 Kubernetes 接受了请求，不代表容器已经成功运行。</p><h3 id="为什么还要打开浏览器访问" tabindex="-1"><a class="header-anchor" href="#为什么还要打开浏览器访问" aria-hidden="true">#</a> 为什么还要打开浏览器访问？</h3><p>因为 <code>Running</code> 不等于业务内容正确。真实请求成功才是更进一步的证据。</p><h3 id="_18080-80-两边分别是什么" tabindex="-1"><a class="header-anchor" href="#_18080-80-两边分别是什么" aria-hidden="true">#</a> <code>18080:80</code> 两边分别是什么？</h3><p>左边 <code>18080</code> 是你的 Mac 端口，右边 <code>80</code> 是 Nginx 在 Pod 中使用的端口。</p><h3 id="port-forward-是正式发布方式吗" tabindex="-1"><a class="header-anchor" href="#port-forward-是正式发布方式吗" aria-hidden="true">#</a> <code>port-forward</code> 是正式发布方式吗？</h3><p>不是。它适合学习和临时调试，命令停止后通道就消失。</p><h3 id="pod-启动卡住-先看什么" tabindex="-1"><a class="header-anchor" href="#pod-启动卡住-先看什么" aria-hidden="true">#</a> Pod 启动卡住，先看什么？</h3><p>先用 <code>kubectl get pod</code> 看状态，再用 <code>kubectl describe pod Pod名称</code> 查看底部 Events。</p><h2 id="本课只记住四件事" tabindex="-1"><a class="header-anchor" href="#本课只记住四件事" aria-hidden="true">#</a> 本课只记住四件事</h2><ol><li>Pod 是 Kubernetes 运行应用的最小单位。</li><li><code>kubectl apply -f</code> 根据 YAML 创建对象。</li><li>创建成功、Pod Running、网页可访问是三个不同层次。</li><li>初步验证顺序是状态 → Events → 实际请求 → 日志。</li></ol><h2 id="下一课预告" tabindex="-1"><a class="header-anchor" href="#下一课预告" aria-hidden="true">#</a> 下一课预告</h2><p>下一课以刚才运行过的 YAML 为基础，只解释 <code>apiVersion</code>、<code>kind</code>、<code>metadata</code>、<code>spec</code> 四块。先见过结果，再学习字段。</p>`,95),t=[i];function l(r,c){return a(),d("div",null,t)}const u=e(s,[["render",l],["__file","03-第二课-亲手运行第一个应用.html.vue"]]);export{u as default};
